def source(sid,title,url,summary,creators=None,publisher='',year='2026',locator=''):
 r=source_record(sid,title,'public_source',url,summary,creators or [],publisher,year,quality='B')
 r.update(connection_pass=MARK,last_checked=DATE,review_status='source_scoped_research_pass',source_locator=locator)
