def node(nid,title,kind,summary,sids,tags=None):
 i=int(hashlib.sha256(nid.encode()).hexdigest()[:6],16)
 r=node_record(nid,title,kind,summary,sids,round(.55+.2*math.cos(i*2.4),6),round(.45+.2*math.sin(i*2.4),6),tags or [])
 r.update(connection_pass=MARK,status='candidate',review_status='research_pass_needs_editor',reviewed_by='',reviewed_at='',inclusion_reason=MARK,set_tags=enc(['systems','release_0_31',*(tags or [])]))
 upsert(d['nodes'],[r],'id');return nid
def edge(eid,a,b,typ,sid,locator,scope):
 family=next(r['relation_family'] for r in d['relation_types'] if r['relation_type']==typ)
 r=edge_record(eid,a,b,typ,family,typ.replace('_',' '),[sid],locator,scope,status='candidate',confidence='',review_label='Located source statement; curator review pending')
 vid='ev_'+eid;cid='claim_'+eid;r.update(connection_pass=MARK,evidence_ids=enc([vid]),claim_id=cid)
 upsert(d['edges'],[r],'id')
