 upsert(d['claims'],[dict(id=cid,statement=scope,subject_id=a,predicate=typ,object_id=b,status='candidate',supporting_source_ids=enc([sid]),supporting_evidence_ids=enc([vid]),contradicting_source_ids='[]',contradicting_evidence_ids='[]',notes='Source-scoped interpretation. Human editorial acceptance remains pending.',review_status='research_pass_needs_editor',reviewed_by='',reviewed_at='',connection_pass=MARK)],'id')
