def link(url,title):return '<a href="'+E(url)+'">'+E(title)+'</a>'
def atlas(nid,title):return link('/#view=item&id='+nid,title)
def details(title,body):return '<details><summary>'+E(title)+'</summary>'+body+'</details>'
body='<p>Start with the question you need to explore, then choose a learning setting. This directory brings together open materials, courses, programmes, society resources, and the atlas’s own practice routes.</p><p class="note">Access labels describe the listed route, not every resource or qualification offered by a provider. Provider pages determine current dates, fees, and admission. Benjamin P Taylor has professional roles at RedQuadrant and PSTA.</p><div class="filters"><label>Find a learning route<input id="learningSearch" type="search" placeholder="Provider, method, or topic"></label><label>Access<select id="learningAccess"><option value="">All access types</option><option value="open">Open or free routes</option><option value="provider">Provider terms</option><option value="mixed">Mixed access</option></select></label></div><p id="learningCount" role="status"></p><div class="grid" id="learningRoutes">'
for r in P['training']:
 access='open' if any(x in r['access'].lower() for x in ['open','free']) else 'mixed' if r['access']=='Mixed access' else 'provider'
 body+='<article data-access="'+access+'"><p class="meta">'+E(r['provider'])+' · '+E(r['format'])+'</p><h2>'+link(r['url'],r['title'])+'</h2><p>'+E(r['summary'])+'</p><p class="status">'+E(r['access'])+' · checked '+r['checked']+'</p></article>'
body+='</div><section><h2>Find a live gathering</h2><p>'+link('/events/','Events, society meetings, and calendar subscriptions')+'. The learning directory holds enduring routes; the events collection holds dated listings.</p></section>'
script='''<script>(()=>{const q=document.getElementById('learningSearch'),a=document.getElementById('learningAccess'),cards=[...document.querySelectorAll('#learningRoutes article')];const sp=new URLSearchParams(location.search);q.value=sp.get('q')||'';a.value=sp.get('access')||'';function filter(write){const term=q.value.trim().toLowerCase();let n=0;for(const c of cards){c.hidden=!(c.textContent.toLowerCase().includes(term)&&(!a.value||c.dataset.access===a.value));if(!c.hidden)n++;}document.getElementById('learningCount').textContent=n+' of '+cards.length+' learning routes';if(write){const p=new URLSearchParams();if(q.value)p.set('q',q.value);if(a.value)p.set('access',a.value);history.replaceState(null,'',location.pathname+(p.size?'?'+p:''));}}q.addEventListener('input',()=>filter(true));a.addEventListener('change',()=>filter(true));filter(false);})();</script>'''
